import React, { useState, useRef, useCallback } from 'react';
import axios from 'axios';

const VirtualTryOn = ({ product }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [personImage, setPersonImage] = useState(null);   // { file, preview }
    const [resultUrl, setResultUrl] = useState(null);
    const [status, setStatus] = useState('idle'); // idle | uploading | processing | done | error
    const [errorMsg, setErrorMsg] = useState('');
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef(null);

    const garmentImageUrl = product?.images?.[0];

    const reset = () => {
        setPersonImage(null);
        setResultUrl(null);
        setStatus('idle');
        setErrorMsg('');
    };

    const handleClose = () => {
        setIsOpen(false);
        setTimeout(reset, 300);
    };

    // Convert File → base64 data URI
    const toBase64 = (file) => new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });

    const handleFile = useCallback((file) => {
        if (!file || !file.type.startsWith('image/')) return;
        const preview = URL.createObjectURL(file);
        setPersonImage({ file, preview });
        setResultUrl(null);
        setStatus('idle');
        setErrorMsg('');
    }, []);

    const handleDrop = useCallback((e) => {
        e.preventDefault();
        setIsDragging(false);
        const file = e.dataTransfer.files[0];
        handleFile(file);
    }, [handleFile]);

    const handleTryOn = async () => {
        if (!personImage?.file) return;
        setStatus('uploading');
        setResultUrl(null);
        setErrorMsg('');

        try {
            const base64 = await toBase64(personImage.file);
            setStatus('processing');

            const { data } = await axios.post(
                'http://localhost:5001/api/tryon',
                {
                    personImageBase64: base64,
                    garmentImageUrl,
                    garmentDescription: product?.name || 'clothing item',
                },
                { timeout: 120000 } // 2 min timeout
            );

            setResultUrl(data.resultUrl);
            setStatus('done');
        } catch (err) {
            console.error('Try-on failed:', err);
            const msg = err.response?.data?.error || 'Something went wrong. Please try again.';
            setErrorMsg(msg);
            setStatus('error');
        }
    };

    const handleDownload = async () => {
        if (!resultUrl) return;
        try {
            const response = await fetch(resultUrl);
            const blob = await response.blob();
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `bindass-tryon-${Date.now()}.jpg`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        } catch {
            // Fallback: open in new tab
            window.open(resultUrl, '_blank');
        }
    };

    return (
        <>
            {/* ── Copilot-Style Button ── */}
            <button
                onClick={() => setIsOpen(true)}
                className="group relative flex items-center gap-2.5 px-5 py-3 rounded-full font-['Manrope'] font-bold text-[11px] uppercase tracking-widest transition-all duration-300 overflow-hidden"
                style={{
                    background: 'linear-gradient(135deg, #10221c 0%, #1a3d32 50%, #0d6e4b 100%)',
                    boxShadow: '0 0 20px rgba(17, 212, 144, 0.25), 0 2px 8px rgba(0,0,0,0.15)',
                }}
                title="Virtual Try-On with AI"
            >
                {/* Animated shimmer */}
                <span className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-700 ease-in-out" />

                {/* AI Sparkle icon (Copilot-style) */}
                <span className="relative w-5 h-5 flex-shrink-0">
                    <svg viewBox="0 0 24 24" fill="none" className="w-full h-full">
                        <defs>
                            <linearGradient id="tryonGrad" x1="0" y1="0" x2="1" y2="1">
                                <stop offset="0%" stopColor="#11d490" />
                                <stop offset="100%" stopColor="#4ade80" />
                            </linearGradient>
                        </defs>
                        <path strokeLinecap="round" strokeLinejoin="round" stroke="url(#tryonGrad)" strokeWidth="1.5"
                            d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" />
                        <path strokeLinecap="round" strokeLinejoin="round" stroke="url(#tryonGrad)" strokeWidth="1.5"
                            d="M18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456z" />
                    </svg>
                </span>

                <span className="relative text-white">Try It On</span>

                {/* Pulse dot */}
                <span className="relative flex h-2 w-2">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-60"></span>
                    <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-300"></span>
                </span>
            </button>

            {/* ── Modal Backdrop ── */}
            <div
                className={`fixed inset-0 z-[300] bg-black/70 backdrop-blur-sm transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
                onClick={handleClose}
            />

            {/* ── Modal Panel ── */}
            <div
                className={`fixed inset-0 sm:inset-auto sm:top-1/2 sm:left-1/2 z-[310] w-full sm:w-[680px] max-h-screen sm:max-h-[90vh] sm:-translate-x-1/2 sm:-translate-y-1/2 bg-white sm:rounded-2xl shadow-2xl flex flex-col overflow-hidden transition-all duration-400 ${
                    isOpen ? 'opacity-100 scale-100' : 'opacity-0 scale-95 pointer-events-none'
                }`}
                style={{ transition: 'opacity 0.3s ease, transform 0.3s cubic-bezier(0.34, 1.3, 0.64, 1)' }}
            >
                {/* Header */}
                <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 flex-shrink-0"
                    style={{ background: 'linear-gradient(135deg, #10221c, #1a3d32)' }}
                >
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center border border-white/20">
                            <svg viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="1.5" className="w-4 h-4">
                                <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" />
                            </svg>
                        </div>
                        <div>
                            <p className="text-white font-bold text-sm tracking-wide font-['Manrope']">Virtual Try-On</p>
                            <p className="text-emerald-300 text-[9px] uppercase tracking-[0.2em] font-medium font-['Manrope']">Powered by AI · Images are never saved</p>
                        </div>
                    </div>
                    <button onClick={handleClose} className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 flex items-center justify-center transition-colors">
                        <svg viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" className="w-4 h-4">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>

                {/* Body */}
                <div className="flex-1 overflow-y-auto p-5 md:p-6" style={{ scrollbarWidth: 'none' }}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">

                        {/* Left: Garment preview */}
                        <div>
                            <p className="text-[10px] font-bold uppercase tracking-widest text-gray-400 mb-3 font-['Manrope']">Garment</p>
                            <div className="aspect-[3/4] bg-gray-50 rounded-xl overflow-hidden border border-gray-100">
                                {garmentImageUrl ? (
                                    <img src={garmentImageUrl} alt={product?.name} className="w-full h-full object-cover" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center text-gray-300 text-xs">No image</div>
                                )}
                            </div>
                            <p className="text-xs font-semibold text-[#10221c] mt-2 truncate font-['Manrope']">{product?.name}</p>
                        </div>

                        {/* Right: Person upload / Result */}
                        <div>
                            <p className="text-[10px] font-bold uppercase tracking-widest text-gray-400 mb-3 font-['Manrope']">
                                {status === 'done' ? 'Your Try-On Result' : 'Your Photo'}
                            </p>

                            {status === 'done' && resultUrl ? (
                                <div className="aspect-[3/4] rounded-xl overflow-hidden border-2 border-emerald-200 relative">
                                    <img src={resultUrl} alt="Try-on result" className="w-full h-full object-cover" />
                                    <div className="absolute top-2 right-2 bg-emerald-500 text-white text-[9px] font-bold uppercase tracking-widest px-2 py-1 rounded-full font-['Manrope']">
                                        AI Generated
                                    </div>
                                </div>
                            ) : (
                                <div
                                    className={`aspect-[3/4] rounded-xl border-2 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all ${
                                        isDragging ? 'border-emerald-400 bg-emerald-50' : personImage ? 'border-gray-200 p-0 overflow-hidden' : 'border-gray-200 hover:border-gray-400 bg-gray-50'
                                    }`}
                                    onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                                    onDragLeave={() => setIsDragging(false)}
                                    onDrop={handleDrop}
                                    onClick={() => !personImage && fileInputRef.current?.click()}
                                >
                                    {personImage ? (
                                        <div className="relative w-full h-full">
                                            <img src={personImage.preview} alt="You" className="w-full h-full object-cover rounded-xl" />
                                            {(status === 'uploading' || status === 'processing') && (
                                                <div className="absolute inset-0 bg-black/50 rounded-xl flex flex-col items-center justify-center gap-3">
                                                    <div className="w-10 h-10 border-2 border-emerald-400 border-t-transparent rounded-full animate-spin" />
                                                    <p className="text-white text-xs font-bold font-['Manrope'] uppercase tracking-widest">
                                                        {status === 'uploading' ? 'Preparing...' : 'Generating...'}
                                                    </p>
                                                </div>
                                            )}
                                            {status !== 'processing' && status !== 'uploading' && (
                                                <button
                                                    onClick={(e) => { e.stopPropagation(); reset(); fileInputRef.current?.click(); }}
                                                    className="absolute top-2 right-2 bg-white/90 rounded-full p-1.5 hover:bg-white transition-colors shadow"
                                                >
                                                    <svg viewBox="0 0 24 24" fill="none" stroke="#10221c" strokeWidth="2" className="w-3.5 h-3.5">
                                                        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                                                    </svg>
                                                </button>
                                            )}
                                        </div>
                                    ) : (
                                        <div className="text-center px-4">
                                            <div className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-3">
                                                <svg viewBox="0 0 24 24" fill="none" stroke="#9ca3af" strokeWidth="1.5" className="w-6 h-6">
                                                    <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5m-13.5-9L12 3m0 0l4.5 4.5M12 3v13.5" />
                                                </svg>
                                            </div>
                                            <p className="text-xs font-bold text-gray-700 mb-1 font-['Manrope']">Upload your photo</p>
                                            <p className="text-[10px] text-gray-400 font-['Manrope']">Drag & drop or click to browse</p>
                                            <p className="text-[9px] text-gray-300 mt-2 font-['Manrope']">Full-body photo works best</p>
                                        </div>
                                    )}
                                </div>
                            )}

                            <input
                                ref={fileInputRef}
                                type="file"
                                accept="image/*"
                                className="hidden"
                                onChange={e => handleFile(e.target.files[0])}
                            />
                        </div>
                    </div>

                    {/* Error */}
                    {status === 'error' && (
                        <div className="mt-4 p-3 bg-red-50 border border-red-100 rounded-lg text-xs text-red-600 font-['Manrope']">
                            ⚠️ {errorMsg}
                        </div>
                    )}

                    {/* Tips */}
                    {status === 'idle' && !personImage && (
                        <div className="mt-5 p-4 bg-[#f0fdf4] rounded-xl border border-emerald-100">
                            <p className="text-[10px] font-bold uppercase tracking-widest text-emerald-700 mb-2 font-['Manrope']">Tips for best results</p>
                            <ul className="text-[11px] text-emerald-800 space-y-1 font-['Manrope']">
                                <li>• Use a clear, well-lit full-body photo</li>
                                <li>• Stand facing the camera with arms slightly out</li>
                                <li>• Wear simple, form-fitting clothing in your photo</li>
                                <li>• Plain or light-coloured backgrounds work best</li>
                            </ul>
                        </div>
                    )}
                </div>

                {/* Footer Actions */}
                <div className="flex-shrink-0 px-5 md:px-6 py-4 border-t border-gray-100 flex items-center gap-3">
                    {status === 'done' ? (
                        <>
                            <button
                                onClick={handleDownload}
                                className="flex-1 flex items-center justify-center gap-2 py-3.5 bg-[#10221c] text-white text-[11px] font-bold uppercase tracking-widest font-['Manrope'] rounded-xl hover:bg-emerald-950 transition-colors"
                            >
                                <svg viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" className="w-4 h-4">
                                    <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5M16.5 12L12 16.5m0 0L7.5 12m4.5 4.5V3" />
                                </svg>
                                Download Image
                            </button>
                            <button
                                onClick={() => { setStatus('idle'); setResultUrl(null); }}
                                className="px-5 py-3.5 border border-gray-200 text-gray-600 text-[11px] font-bold uppercase tracking-widest font-['Manrope'] rounded-xl hover:border-gray-400 transition-colors"
                            >
                                Try Again
                            </button>
                        </>
                    ) : (
                        <>
                            <button
                                onClick={handleTryOn}
                                disabled={!personImage || status === 'processing' || status === 'uploading'}
                                className={`flex-1 flex items-center justify-center gap-2 py-3.5 text-[11px] font-bold uppercase tracking-widest font-['Manrope'] rounded-xl transition-all ${
                                    personImage && status === 'idle' || status === 'error'
                                        ? 'text-white hover:opacity-90 active:scale-95'
                                        : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                                }`}
                                style={personImage && (status === 'idle' || status === 'error') ? {
                                    background: 'linear-gradient(135deg, #10221c, #0d6e4b)',
                                    boxShadow: '0 4px 15px rgba(17,212,144,0.2)'
                                } : {}}
                            >
                                {(status === 'uploading' || status === 'processing') ? (
                                    <>
                                        <div className="w-4 h-4 border-2 border-white/40 border-t-white rounded-full animate-spin" />
                                        {status === 'uploading' ? 'Preparing...' : 'AI Generating...'}
                                    </>
                                ) : (
                                    <>
                                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" className="w-4 h-4">
                                            <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" />
                                        </svg>
                                        Generate Try-On
                                    </>
                                )}
                            </button>
                            {!personImage && (
                                <button
                                    onClick={() => fileInputRef.current?.click()}
                                    className="px-5 py-3.5 border border-gray-200 text-gray-600 text-[11px] font-bold uppercase tracking-widest font-['Manrope'] rounded-xl hover:border-gray-400 transition-colors"
                                >
                                    Upload Photo
                                </button>
                            )}
                        </>
                    )}
                </div>
            </div>
        </>
    );
};

export default VirtualTryOn;
